const S={step:'offer',search:null,offers:[],searchErrors:[],searchLoading:false,searchFailed:false,cart:null,extras:[],selectedExtras:new Map(),transfers:[],selectedTransfer:null,seatMaps:[],seatTravelers:[],seatSelections:{},activeSeatMap:0,activeSeatTraveler:0,rules:null,travelers:[],contact:{},payment:null,confirmation:null,documents:null,awaiting:false,initializing:true,canBackToResults:false,paymentBusy:false,paymentSubmitted:false,stripe:null,elements:null,paymentElement:null,handshakeSeen:false,openFlight:'',openDetails:'',selectedCabins:{},upsells:{}};
const el=id=>document.getElementById(id);
const esc=(v='')=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
