function renderFlightDetails(offer){const slices=arr(offer.slices);return `<div class="flight-details">${slices.map((slice,i)=>`<section><h4>${i===0?'Outbound':'Return'} · ${esc(durationText(durationMinutes(slice.duration))||'Journey duration unavailable')}</h4>${arr(slice.segments).map((segment,j,segments)=>{const marketing=segment.marketingCarrier||{},operating=segment.operatingCarrier||{},flight=[marketing.iataCode,segment.marketingFlightNumber].filter(Boolean).join(' '),different=operating.name&&((operating.iataCode&&marketing.iataCode&&operating.iataCode!==marketing.iataCode)||(!operating.iataCode&&operating.name!==marketing.name));return `<div class="flight-detail-segment"><strong>${esc(endpoint(segment.origin))} → ${esc(endpoint(segment.destination))} · ${esc(flight||'Flight number unavailable')}</strong><span>${esc(flightDate(segment.departingAt))} ${esc(flightClock(segment.departingAt))} – ${esc(flightDate(segment.arrivingAt))} ${esc(flightClock(segment.arrivingAt))} · ${esc(durationText(durationMinutes(segment.duration))||'Flight time unavailable')}</span><span>${esc(marketing.name||'Airline unavailable')}${different?` · Operated by ${esc(operating.name)}`:''} · ${esc(segment.aircraft?.name||segment.aircraft?.iataCode||'Aircraft not provided')}</span><span>${esc(mealSummary(segment))}</span>${arr(segment.stops).map(stop=>`<span>Stop at ${esc(endpoint(stop.airport)||'airport')} ${esc(durationText(durationMinutes(stop.duration)))}</span>`).join('')}</div>${j<segments.length-1?`<div class="flight-transfer">${esc(transferText(segment,segments[j+1]))}</div>`:''}`}).join('')}</section>`).join('')}<p class="flight-emissions">${num(offer.totalEmissionsKg)!==null?`Estimated CO₂: ${esc(offer.totalEmissionsKg)} kg for all travelers on the full itinerary.`:'CO₂ estimate not provided for this offer.'}</p></div>`}
